import React, { useEffect, useRef } from 'react';
import LogoLoop from './LogoLoop';
import './MidSection.css';

/* ── Logo items — SVG from /public + name label ───────────────── */
const logos = [
  {
    node: (
      <span className="ms-logo-item">
        <img
          src={process.env.PUBLIC_URL + '/maptiler.svg'}
          alt=""
          aria-hidden="true"
          className="ms-logo-svg"
        />
        <span className="ms-logo-name">MapTiler</span>
      </span>
    ),
    title: 'MapTiler',
  },
  {
    node: (
      <span className="ms-logo-item">
        <img
          src={process.env.PUBLIC_URL + '/maplibre.svg'}
          alt=""
          aria-hidden="true"
          className="ms-logo-svg"
        />
        <span className="ms-logo-name">MapLibre</span>
      </span>
    ),
    title: 'MapLibre',
  },
  {
    node: (
      <span className="ms-logo-item">
        <img
          src={process.env.PUBLIC_URL + '/openstreetmap.svg'}
          alt=""
          aria-hidden="true"
          className="ms-logo-svg"
        />
        <span className="ms-logo-name">OpenStreetMap</span>
      </span>
    ),
    title: 'OpenStreetMap',
  },
];

/* ─────────────────────────────────────────────────────────────── */

export const MidSection = () => {
  const p1Ref = useRef(null);
  const p2Ref = useRef(null);
  const p3Ref = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          } else {
            entry.target.classList.remove('is-visible');
          }
        });
      },
      { threshold: 0.6, rootMargin: '0px 0px -100px 0px' }
    );

    if (p1Ref.current) observer.observe(p1Ref.current);
    if (p2Ref.current) observer.observe(p2Ref.current);
    if (p3Ref.current) observer.observe(p3Ref.current);

    return () => observer.disconnect();
  }, []);

  return (
    <section className="ms-section" aria-label="About Dishastra">

      {/* ── Intro paragraphs ─────────────────────────────────────── */}
      <div className="ms-intro-wrap">

        {/* Para 1 — primary, white, larger */}
        <p ref={p1Ref} className="ms-para ms-para--primary">
          Dishastra is a conversational travel planner that turns a single
          prompt into a fully planned adventure. Just describe your ideal
          getaway, and watch it generate an optimised, day&#8209;by&#8209;day
          itinerary in seconds.
        </p>

        {/* Para 2 — secondary, dimmed */}
        <p ref={p2Ref} className="ms-para ms-para--secondary">
          Designed to be effortlessly intuitive, the platform features a clean
          Minimalist Mode. It strips away complex settings, providing a
          distraction&#8209;free interface that makes advanced trip planning
          accessible to absolutely everyone.
        </p>

        {/* Para 3 — primary, white, larger */}
        <p ref={p3Ref} className="ms-para ms-para--primary">
          From initial discovery to on&#8209;the&#8209;go guidance, Dishastra
          handles the heavy lifting. Export your complete itinerary with a
          single tap and focus entirely on the adventure, even when you drop
          off the grid.
        </p>
      </div>

      {/* ── Powered By ───────────────────────────────────────────── */}
      <div className="ms-powered-wrap">
        {/* Label — top half white, bottom half metallic silver */}
        <p className="ms-powered-label" aria-label="Powered by">
          POWERED BY
        </p>

        {/* Infinite logo marquee */}
        <div className="ms-marquee-wrap">
          <LogoLoop
            logos={logos}
            speed={40}
            direction="left"
            logoHeight={40}
            gap={100}
            hoverSpeed={0}
            fadeOut
            fadeOutColor="#000000"
            ariaLabel="Technologies powering Dishastra"
          />
        </div>
      </div>

    </section>
  );
};
